10: pub fn cmd_lsp() -> Result<()> {
11:     let stdin = io::stdin();
12:     let mut stdin_lock = stdin.lock();
13:     let stdout = io::stdout();
14:     let mut stdout_lock = stdout.lock();
15: 
16:     loop {
17:         let mut content_length: Option<usize> = None;
18:         let mut line = String::new();
19: 
20:         loop {
21:             line.clear();
22:             if stdin_lock.read_line(&mut line).unwrap_or(0) == 0 {
23:                 return Ok(()); // EOF
24:             }
25:             if line == "\r\n" || line == "\n" {
26:                 break;
27:             }
28:             if let Some(header) = line.strip_prefix("Content-Length: ") {
29:                 content_length = header.trim().parse().ok();
30:             }
31:         }
32: 
33:         let Some(len) = content_length else {
34:             continue;
35:         };
36: 
37:         let mut buf = vec![0u8; len];
38:         if stdin_lock.read_exact(&mut buf).is_err() {
39:             return Ok(());
40:         }
41: 
42:         let Ok(msg) = serde_json::from_slice::<serde_json::Value>(&buf) else {
43:             continue;
44:         };
45: 
46:         if let Some(method) = msg["method"].as_str() {
47:             let id = msg.get("id");
48:             match method {
49:                 "initialize" => {
50:                     if let Some(id) = id {
51:                         let response = serde_json::json!({
52:                             "jsonrpc": "2.0",
53:                             "id": id,
54:                             "result": {
55:                                 "capabilities": {
56:                                     "textDocumentSync": 1,
57:                                     "hoverProvider": true
58:                                 },
59:                                 "serverInfo": {
60:                                     "name": "oxc-react-docgen-lsp",
61:                                     "version": env!("CARGO_PKG_VERSION")
62:                                 }
63:                             }
64:                         });
65:                         send_response(&mut stdout_lock, &response);
66:                     }
67:                 }
68:                 "shutdown" => {
69:                     if let Some(id) = id {
70:                         let response = serde_json::json!({
71:                             "jsonrpc": "2.0",
72:                             "id": id,
73:                             "result": null
74:                         });
75:                         send_response(&mut stdout_lock, &response);
76:                     }
77:                 }
78:                 "exit" => break,
79:                 _ => {}
80:             }
81:         }
82:     }
83: 
84:     Ok(())
85: }
86: 
87: fn send_response<W: Write>(out: &mut W, response: &serde_json::Value) {
88:     if let Ok(json) = serde_json::to_string(response) {
89:         let header = format!("Content-Length: {}\r\n\r\n", json.len());
90:         let _ = out.write_all(header.as_bytes());
91:         let _ = out.write_all(json.as_bytes());
92:         let _ = out.flush();
93:     }
94: }
