12:     /// Unique plugin name identifier.
13:     fn name(&self) -> &str;
14: 
15:     /// Invoked after AST extraction for a single file (`SourceData`).
16:     fn on_file_extracted(&self, _file_path: &camino::Utf8Path, _data: &mut SourceData) {}
17: 
18:     /// Invoked after a component has been fully resolved into a `ComponentEntry`.
19:     fn on_component_resolved(&self, _entry: &mut ComponentEntry) {}
20: }
