12:     /// Unique plugin name identifier.
13:     fn name(&self) -> &str;
14: 
15:     /// Invoked after AST extraction for a single file (`SourceData`).
16:     fn on_file_extracted(&self, _file_path: &camino::Utf8Path, _data: &mut SourceData) {}
17: 
18:     /// Invoked after a component has been fully resolved into a `ComponentEntry`.
19:     fn on_component_resolved(&self, _entry: &mut ComponentEntry) {}
20: }
21: 
22: impl std::fmt::Debug for dyn DocgenPlugin {
23:     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
24:         f.debug_struct("DocgenPlugin").field("name", &self.name()).finish()
25:     }
26: }
27: 
28: /// A registry holding active plugins for a pipeline run.
29: #[derive(Default, Clone)]
30: pub struct PluginRegistry {
31:     plugins: Vec<Arc<dyn DocgenPlugin>>,
32: }
33: 
34: impl PluginRegistry {
35:     pub fn new() -> Self {
36:         Self { plugins: Vec::new() }
37:     }
38: 
39:     pub fn register<P: DocgenPlugin + 'static>(&mut self, plugin: P) {
40:         self.plugins.push(Arc::new(plugin));
